{
  "body": "Code Mode V2 completed with 1 tool call.

package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"

	"github.com/modelcontextprotocol/go-sdk/mcp"

	"tidecode-fs-mcp-go/internal/tidecode"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run(args []string) error {
	defaultHost := strings.TrimSpace(os.Getenv("MCP_HTTP_HOST"))
	if defaultHost == "" {
		defaultHost = tidecode.DefaultHTTPHost
	}
	defaultPort := tidecode.DefaultHTTPPort
	if rawPort := strings.TrimSpace(os.Getenv("MCP_HTTP_PORT")); rawPort != "" {
		parsedPort, err := strconv.Atoi(rawPort)
		if err != nil || parsedPort < 0 || parsedPort > 65535 {
			return errors.New("MCP_HTTP_PORT must be an integer between 0 and 65535.")
		}
		defaultPort = parsedPort
	}

	flags := flag.NewFlagSet("tidecode-fs-mcp", flag.ContinueOnError)
	flags.SetOutput(os.Stdout)
	httpMode := flags.Bool("http", false, "serve MCP over Streamable HTTP instead of stdio")
	disableAuth := flags.Bool("disable-auth", false, "disable HTTP OAuth; allowed only when binding to loopback")
	host := flags.String("host", defaultHost, "HTTP bind host")
	port := defaultPort
	flags.IntVar(&port, "port", defaultPort, "HTTP bind port")
	flags.IntVar(&port, "p", defaultPort, "HTTP bind port")
	publicURL := flags.String("public-url", strings.TrimSpace(os.Getenv("MCP_PUBLIC_URL")), "public MCP URL used for OAuth metadata")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	if *httpMode {
		running, err := tidecode.StartHTTPServer(tidecode.HTTPServerOptions{
			DisableAuth: *disableAuth,
			Host:        *host,
			Port:        port,
			PortSet:     true,
			PublicURL:   *publicURL,
		})
		if err != nil {
			return err
		}
		defer running.Close()
		fmt.Fprintf(os.Stderr, "[http] tidecode-fs-mcp listening on http://%s:%d%s\n", running.Address.Host, running.Address.Port, tidecode.DefaultMCPPath)
		<-ctx.Done()
		return running.Close()
	}

	app := tidecode.CreateMCPServer(tidecode.PlannerServerOptions{})
	defer app.Close()
	return app.Server.Run(ctx, &mcp.StdioTransport{})
}",
