	flags.SetOutput(os.Stdout)
	httpMode := flags.Bool("http", false, "serve MCP over Streamable HTTP instead of stdio")
	disableAuth := flags.Bool("disable-auth", false, "disable HTTP OAuth; allowed only when binding to loopback")
	host := flags.String("host", defaultHost, "HTTP bind host")
	port := defaultPort
	flags.IntVar(&port, "port", defaultPort, "HTTP bind port")
	flags.IntVar(&port, "p", defaultPort, "HTTP bind port")
	publicURL := flags.String("public-url", strings.TrimSpace(os.Getenv("MCP_PUBLIC_URL")), "public MCP URL used for OAuth metadata")
	if err := flags.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			return nil
		}
		return err
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	if *httpMode {
		running, err := tidecode.StartHTTPServer(tidecode.HTTPServerOptions{
			DisableAuth: *disableAuth,
			Host:        *host,
			Port:        port,
			PortSet:     true,
			PublicURL:   *publicURL,
		})
		if err != nil {
			return err
		}
