		fmt.Fprintf(os.Stderr, "[http] tidecode-fs-mcp listening on http://%s:%d%s\n", running.Address.Host, running.Address.Port, tidecode.DefaultMCPPath)
		<-ctx.Done()
		return running.Close()
	}

	app := tidecode.CreateMCPServer(tidecode.PlannerServerOptions{})
	defer app.Close()
	return app.Server.Run(ctx, &mcp.StdioTransport{})
