{
  "body": "Code Mode V2 completed with 1 tool call.

package tidecode

import (
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

const serverName = "tidecode-fs-mcp"
const serverVersion = "2.3.0"

type PlannerServerOptions struct {
	TerminalService      *TerminalService
	TerminalOwnerKey     string
	Scopes               ScopeSet
	RequireTerminalScope bool
	TerminalScope        string
}

type PlannerMCPServer struct {
	Server       *mcp.Server
	terminal     *TerminalService
	ownsTerminal bool
}

func boolPtr(v bool) *bool { return &v }

func codeModePayloadsFromInput(value any) (map[string]string, error) {
	if value == nil {
		return nil, nil
	}
	raw, ok := value.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("payloads must be an object whose values are strings")
	}
	payloads := make(map[string]string, len(raw))
	for key, value := range raw {
		text, ok := value.(string)
		if !ok {
			return nil, fmt.Errorf("payloads.%s must be a string", key)
		}
		payloads[key] = text
	}
	return payloads, nil
}

func workspaceFromMCPInput(input map[string]any) (string, error) {
	workspaceRaw, ok := input["workspace_path"].(string)
	if !ok || strings.TrimSpace(workspaceRaw) == "" || !filepath.IsAbs(strings.TrimSpace(workspaceRaw)) {
		return "", fmt.Errorf("workspace_path must be a non-empty absolute path")
	}
	return resolveWorkspace(workspaceRaw)
}

func buildTCodeModeDescription(registries ...*ToolRegistry) string {
	lines := []string{
		"Execute one free-form temporary asynchronous Tidecode Code Mode program for orchestration. Return concise JSON-compatible data.",
		"The model-facing MCP surface also includes direct write and apply_patch tools. Use direct write for complete-file creation/replacement and direct apply_patch for targeted patches; neither operation is available as tools.write/tools.apply_patch inside Code Mode.",
		"For arbitrary multiline or syntax-heavy text that genuinely must enter a remaining Code Mode capability, put the exact text in the outer payloads object and reference it inside Code Mode as payloads.<name>. Payload text is inert data and is never parsed as JavaScript.",
		"Tidecode Code Mode is an owned orchestration language, not a Node.js host runtime. Use tools.* for filesystem, terminal, process, network, memory, plan, mutation, and connected-service actions. tools.execute_terminal runs real host commands with the access granted to the MCP process.",
		"Node.js globals and modules such as `global`, `process`, `require`, `module`, `fs` / `node:fs`, `child_process`, `http`, `https`, `net`, `fetch`, `Worker`, `Buffer`, `Electron`, `Bun`, and `Deno` are not Code Mode language globals. Use the documented tools.* APIs or tools.execute_terminal for host operations instead.",
		"Unsupported executable language/runtime constructs are rejected before tool execution so they cannot cause a partial tools.* mutation. Non-executable literal text such as strings, comments, regex literals, and template-literal text may still contain those names.",
		"Every tools.* call returns a Promise-compatible ToolResult. Await it or explicitly chain it before depending on completion. Failed tools reject unless explicitly caught, and any failed tool call keeps the overall Code Mode result in an error state even when the program recovers and continues.",
		"Tool arguments are validated before native execution. Unsupported false flags are ignored for small-model compatibility, while unsupported truthy properties and invalid types or numeric bounds are rejected before the underlying tool runs.",
		"The outer workspace_path selects the project for this entire invocation. Nested tools.* calls do not accept workspace_path; they are automatically bound to that project.",
		"Planning-first rule: inspect current state before changing it. Questions, reviews, diagnosis, and planning requests do not authorize source mutation. When the user explicitly requests implementation or execution, use the direct apply_patch/write tools or terminal as needed and verify the requested result.",
		"Path rule: Treat a file path as known only when the user supplied it or a prior workspace tool returned that exact path. Never invent a likely filename from project conventions. If the exact path is unknown, discover it with `list`, `glob`, or `grep` before `read` or mutation. read/list/glob/grep accept omitted path, empty string, or '.' as the workspace root. Mutation paths must be non-empty.",
		"Preloaded Tidecode APIs:",
		"- payloads.<name> — Read an opaque outer text payload. Bracket access also works. Payloads are read-only and preserve arbitrary text exactly, including Markdown triple-backtick fences. Use payloads only when arbitrary text genuinely must enter a remaining Code Mode capability.",
		"- tools.read({ path?, offset?, limit?, full_file? }) — Read one workspace text file with line numbers, list one directory, or return supported image files as MCP image content the AI can inspect visually. Treat a file path as known only when the user supplied it or a prior workspace tool returned that exact path. Never invent a likely filename from project conventions. If the exact path is unknown, discover it with `list`, `glob`, or `grep` before `read` or mutation. Omitted path or empty string means workspace root.",
		"- tools.list({ path?, offset?, limit? }) — List visible entries in one directory. Omitted path or empty string means workspace root.",
		"- tools.glob({ path?, pattern, offset?, limit? }) — Discover visible workspace files by glob.",
		"- tools.grep({ path?, pattern, include?, offset?, limit? }) — Search visible text files by regular expression.",
		"- tools.memory({ action, folder?, name?, title?, content?, old_text?, new_text? }) — Maintain planner-private memory using logical identifiers.",
		"- tools.plan_create({ content, title? }) — Create the next planner-private draft plan.",
		"- tools.plan_edit({ path, content, title? }) — Replace one managed draft plan.",
		"- tools.skill({ action, query?, name?, page? }) — List, search, or load available workspace and global skills.",
		"- tools.execute_terminal({ command, cwd? }) — Execute a command in a persistent PTY under the selected workspace. Terminal results expose session_id directly and in semantics for follow-up terminal calls; completed results also expose exit_code directly and in semantics.",
		"- tools.read_terminal({ session_id, wait_seconds? }) — Read incremental output from an existing terminal session.",
		"- tools.interact_terminal({ session_id, text?, keys?, cols?, rows?, wait_seconds? }) — Send input, control keys, or resize a terminal session.",
		"- tools.terminate_terminal({ session_id }) — Terminate a persistent terminal session.",
		"- tools.tool_search({ query, namespace?, limit? }) — Discover internal Tidecode APIs and callable signatures.",
	}
	if len(registries) > 0 && registries[0] != nil {
		contract := strings.TrimSpace(registryContract(registries[0]))
		if contract != "" {
			lines = append(lines,
				"",
				"Complete Code Mode tool contracts generated from the live Tidecode registry:",
				contract,
			)
		}
	}
	return strings.Join(lines, "\n")
}

func codeModeToToolResult(result CodeModeResult, workspace string) ToolResult {
	var outputBody string
	media := []MediaPayload{}
	if result.OutputPresent {
		if s, ok := result.Output.(string); ok {
			outputBody = s
		} else {
			outputBody = formatCodeModeOutput(result.Output, result.ToolCalls)
		}
	} else if len(result.ToolCalls) > 0 {
		parts := make([]string, 0, len(result.ToolCalls)+1)
		parts = append(parts, "Code Mode completed tool calls but returned no explicit value.")
		for _, call := range result.ToolCalls {
			text := fmt.Sprintf("%s (%s): %s", call.Name, call.Status, call.Summary)
			if strings.TrimSpace(call.Body) != "" {
				text += "\n" + call.Body
			}
			parts = append(parts, text)
		}
		outputBody = strings.Join(parts, "\n\n")
	}
	body := result.Summary
	if outputBody != "" {
		body += "\n\n" + outputBody
	}
	calls := make([]map[string]any, 0, len(result.ToolCalls))
	for _, call := range result.ToolCalls {
		media = append(media, call.Media...)
		item := map[string]any{
			"arguments":   call.Arguments,
			"duration_ms": call.DurationMS,
			"name":        call.Name,
			"status":      call.Status,
			"summary":     call.Summary,
		}
		compactCodeModeReceiptBody(item, call.Body)
		if call.Semantics != nil {
			item["semantics"] = call.Semantics
		}
		if call.Subject != nil {
			item["subject"] = call.Subject
		}
		calls = append(calls, item)
	}
	status := "success"
	if result.Status != "success" {
		status = "error"
	}
	r := ToolResult{
		Body:      body,
		Status:    status,
		Summary:   result.Summary,
		Subject:   &Subject{Kind: "code_mode", Path: workspace},
		Truncated: result.Truncated,
		Media:     media,
		Semantics: map[string]any{
			"execution_id":    result.ExecutionID,
			"operation":       "tcode_mode",
			"output_limited":  result.Truncated,
			"tool_call_count": len(result.ToolCalls),
			"tool_calls":      calls,
		},
	}
	return r
}

func toolResultMap(r ToolResult) map[string]any {
	b, _ := json.Marshal(r)
	var out map[string]any
	_ = json.Unmarshal(b, &out)
	return out
}

func mcpToolResult(r ToolResult) *mcp.CallToolResult {
	text := r.Summary
	if strings.TrimSpace(r.Body) != "" {
		text = r.Body
		if r.Status == "error" && r.Summary != r.Body {
			text = r.Summary + "\n" + r.Body
		}
	}
	content := []mcp.Content{&mcp.TextContent{Text: text}}
	for _, media := range r.Media {
		if media.Kind == "image" && len(media.Data) > 0 && strings.HasPrefix(media.MIMEType, "image/") {
			content = append(content, &mcp.ImageContent{Data: media.Data, MIMEType: media.MIMEType})
		}
	}
	return &mcp.CallToolResult{
		Content:           content,
		StructuredContent: structuredToolResultMap(r),
		IsError:           r.Status == "error",
	}
}

func CreateMCPServer(options PlannerServerOptions) *PlannerMCPServer {
	return createMCPServer(options)
}

func createMCPServer(options PlannerServerOptions) *PlannerMCPServer {
	terminal := options.TerminalService
	owns := false
	if terminal == nil {
		terminal = NewTerminalService()
		owns = true
	}
	owner := strings.TrimSpace(options.TerminalOwnerKey)
	if owner == "" {
		owner = fmt.Sprintf("local-%d", execCounter.Add(1))
	}
	terminalScope := options.TerminalScope
	if terminalScope == "" {
		terminalScope = "planner:terminal"
	}
	instructions := strings.Join([]string{
		"This server exposes three Tidecode-compatible MCP tools: tcode_mode, write, and apply_patch.",
		"Use direct write for complete-file creation/replacement and direct apply_patch for targeted patches. Do not route those mutations through tcode_mode.",
		"For arbitrary multiline tool data that genuinely must enter another Code Mode capability, use the optional outer payloads object and reference payloads.<name>. Payloads are opaque read-only strings, so do not rewrite Markdown backtick fences or source text merely to avoid JavaScript delimiter conflicts.",
		"Every workspace operation uses an absolute workspace_path. It may come from user input, established conversation state, trusted Tidecode context, configuration, or a prior Tidecode result. Reuse a known workspace instead of requiring the user to repeat it; do not guess an unknown workspace from naming conventions.",
		"Generic read/list/glob/grep may inspect managed plan documents under .tidecode/plans, including .tidecode/plans/plan-###.md. Other .tidecode state such as memory and auth remains private to generic filesystem tools. Generic write/apply_patch must not modify managed plans; use the plan tools for plan changes.",
		"Inside tcode_mode, host actions use the documented tools.* APIs because Code Mode is Tidecode's owned orchestration language rather than a Node.js host runtime. The outer workspace_path is bound once for the whole program. tools.execute_terminal runs real host commands with the MCP process's access.",
		"Node.js globals and module loading are not Code Mode language features. Unsupported executable constructs fail before tools.* calls run, while non-executable strings, comments, regex literals, and template-literal text may contain those names. Generated tool arguments are validated before native execution.",
		"Failed tools reject the JavaScript call unless explicitly caught. Unsupported false flags are ignored for generated-call compatibility, while unsupported truthy properties and invalid argument types or bounds are rejected.",
		"Default to evidence gathering and planning. Questions, reviews, diagnosis, and planning requests do not authorize source mutation. Use direct apply_patch/write or execution only when the user explicitly requests implementation or execution, then verify the requested outcome.",
		"Write project source for humans to read and maintain, not as compressed or minified output. Use conventional formatting for the language and existing file: normal indentation, one meaningful statement per line, expanded control flow, and reasonable line wrapping. Do not pack multiple declarations, assignments, branches, loops, function bodies, or unrelated operations onto one line merely to save space or tokens. Keep naturally short constructs concise when they remain clear. Only produce intentionally compact/minified source when the user explicitly asks for it or the target file is clearly generated/minified and should remain so.",
		"tcode_mode runs Tidecode Code Mode for in-memory orchestration plus tools.* host actions. Supported image reads are emitted as MCP image content for direct visual inspection by the AI. The execute_terminal family provides real terminal/RCE-class host access and remains scope-controlled when OAuth is enabled.",
	}, " ")
	server := mcp.NewServer(&mcp.Implementation{Name: serverName, Version: serverVersion}, &mcp.ServerOptions{Instructions: instructions})
	schema := map[string]any{
		"type":                 "object",
		"additionalProperties": false,
		"properties": map[string]any{
			"code": map[string]any{"type": "string", "minLength": 1, "description": "Free-form temporary asynchronous JavaScript program. Use the documented tools.* APIs for Tidecode operations and return concise JSON-compatible data."},
			"payloads": map[string]any{
				"type":                 "object",
				"description":          "Optional opaque text payloads injected as the read-only Code Mode global payloads. Use these only for arbitrary text that genuinely must enter a remaining Code Mode capability, so it never has to be nested inside JavaScript string/template syntax.",
				"maxProperties":        defaultPayloadCount,
				"propertyNames":        map[string]any{"minLength": 1, "maxLength": defaultPayloadKeyBytes},
				"additionalProperties": map[string]any{"type": "string"},
			},
			"workspace_path": map[string]any{"type": "string", "minLength": 1, "description": "Absolute project root bound to every structured tools.* call in this invocation. Reuse an established trusted workspace when available."},
		},
		"required": []string{"workspace_path", "code"},
	}
	descriptionRegistry := bindCodeModeRegistry("", owner, terminal, options.Scopes)
	tool := &mcp.Tool{
		Name:        "tcode_mode",
		Title:       "Run Tidecode Code Mode",
		Description: buildTCodeModeDescription(descriptionRegistry),
		InputSchema: schema,
		Annotations: &mcp.ToolAnnotations{ReadOnlyHint: false, DestructiveHint: boolPtr(true), IdempotentHint: false},
	}
	mcp.AddTool[map[string]any, any](server, tool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if options.RequireTerminalScope && !options.Scopes.Allows(terminalScope) {
			r := failure("tcode_mode requires the " + terminalScope + " OAuth scope because it can invoke terminal-capable structured tools.")
			return mcpToolResult(r), nil, nil
		}
		code, ok := input["code"].(string)
		if !ok || strings.TrimSpace(code) == "" {
