const defaultReadLines = 500
const maxReadLines = 500
const maxFullReadBytes = 4 << 20
const maxPagedReadBytes = 256 << 10
const maxLineChars = 50000

type ReadService struct{}
type ReadOptions struct {
	Offset   int
	Limit    int
	FullFile bool
}

func (ReadService) Read(root, path string, opts ...ReadOptions) (ToolResult, error) {
	target, err := resolveReadPath(root, path, true)
	if err != nil {
		return ToolResult{}, err
	}
	st, err := os.Stat(target)
	if err != nil {
		return ToolResult{}, err
	}
	workspace, _ := resolveWorkspace(root)
	rel := slashRelative(workspace, target)
	if rel == "" {
		rel = "."
	}
	if st.IsDir() {
		return readDirectory(workspace, target, rel, opts...), nil
	}
	return readFilePaged(target, rel, opts...)
}

func readDirectory(workspace, target, rel string, opts ...ReadOptions) ToolResult {
	entries, _ := os.ReadDir(target)
	names := make([]string, 0, len(entries))
	for _, e := range entries {
		if hiddenName(e.Name()) || e.Type()&os.ModeSymlink != 0 || !genericReadVisible(workspace, filepath.Join(target, e.Name())) {
			continue
		}
		n := e.Name()
		if e.IsDir() {
			n += "/"
		}
		names = append(names, n)
	}
	sort.Slice(names, func(i, j int) bool { return strings.ToLower(names[i]) < strings.ToLower(names[j]) })
	offset, limit := 1, maxReadLines
	if len(opts) > 0 {
		if opts[0].Offset > 0 {
			offset = opts[0].Offset
		}
		if opts[0].Limit > 0 {
			limit = opts[0].Limit
			if limit > maxReadLines {
				limit = maxReadLines
			}
		}
	}
	start := offset - 1
	if start > len(names) {
		start = len(names)
	}
	end := start + limit
	if end > len(names) {
		end = len(names)
	}
	body := "Empty directory"
	if end > start {
		body = strings.Join(names[start:end], "\n")
	}
	r := withSemantics(withSubject(withBody(success("Listed "+rel), body), "directory", rel), map[string]any{"is_directory": true, "offset": offset, "returned_count": end - start, "total_count": len(names), "has_more": end < len(names)})
	return r
}

func readFilePaged(target, rel string, opts ...ReadOptions) (ToolResult, error) {
	if cfg, format, ok := detectSupportedImage(target); ok {
		st, err := os.Stat(target)
		if err != nil {
			return ToolResult{}, err
		}
		return readImageFile(target, rel, st.Size(), cfg, format)
	}
	data, err := os.ReadFile(target)
	if err != nil {
		return ToolResult{}, err
	}
	sample := data
	if len(sample) > 1024 {
		sample = sample[:1024]
	}
	for _, b := range sample {
		if b == 0 {
			return failure("Cannot read binary file: " + rel), nil
		}
	}
	full := false
	offset, limit := 1, defaultReadLines
	if len(opts) > 0 {
		full = opts[0].FullFile
		if opts[0].Offset > 0 {
			offset = opts[0].Offset
		}
		if opts[0].Limit > 0 {
			limit = opts[0].Limit
		}
	}
	maxBytes := maxPagedReadBytes
	if full {
		maxBytes = maxFullReadBytes
		offset = 1
		limit = 1 << 30
	}
	if len(data) > maxBytes && full {
		return failure(fmt.Sprintf("File exceeds full read limit of %d bytes", maxBytes)), nil
	}
	text := normalizeText(string(data))
	lines := strings.Split(text, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	start := offset - 1
	if start < 0 {
		start = 0
	}
	if start > len(lines) {
		start = len(lines)
	}
	end := start + limit
	if end > len(lines) {
		end = len(lines)
	}
	var out strings.Builder
	bytesUsed := 0
	truncatedBytes := false
	actualEnd := end
	for i := start; i < end; i++ {
		line := lines[i]
		if len(line) > maxLineChars {
			line = line[:maxLineChars] + "…"
		}
		rendered := fmt.Sprintf("%d: %s", i+1, line)
		if bytesUsed+len(rendered)+1 > maxBytes {
			truncatedBytes = true
			actualEnd = i
			break
		}
		if out.Len() > 0 {
			out.WriteByte('\n')
		}
		out.WriteString(rendered)
		bytesUsed += len(rendered) + 1
	}
	truncatedLines := actualEnd < len(lines)
	if !truncatedBytes && !truncatedLines {
		if out.Len() > 0 {
			out.WriteString("\n\n")
		}
		out.WriteString(fmt.Sprintf("(End of file - %d lines total)", len(lines)))
	}
	r := withSubject(withBody(success("Read "+rel), out.String()), "file", rel)
	r.Truncated = truncatedBytes || truncatedLines
	r.Semantics = map[string]any{"is_directory": false, "offset": offset, "line_count": len(lines), "truncated_by_bytes": truncatedBytes, "truncated_by_lines": truncatedLines, "full_file": full}
	return r, nil
}

func scanLines(path string, fn func(int, string) bool) error {
	f, err := os.Open(path)
	if err != nil {
		return err
	}
	defer f.Close()
	s := bufio.NewScanner(f)
	buf := make([]byte, 64*1024)
	s.Buffer(buf, maxLineChars*4)
	n := 0
	for s.Scan() {
		n++
		if !fn(n, s.Text()) {
			break
		}
	}
	return s.Err()
