	start := offset - 1
	if start < 0 {
		start = 0
	}
	if start > len(lines) {
		start = len(lines)
	}
	end := start + limit
	if end > len(lines) {
		end = len(lines)
	}
	var out strings.Builder
	bytesUsed := 0
	truncatedBytes := false
	actualEnd := end
