func newCodeModeToolRuntime(ctx context.Context, registry *ToolRegistry, allowed map[string]bool, workspace, executionID string, limits CodeModeLimits) *codeModeToolRuntime {
	concurrency := limits.MaxConcurrentToolCalls
	if concurrency < 1 {
		concurrency = 1
	}
	r := &codeModeToolRuntime{
		registry: registry, allowed: allowed, workspace: workspace, executionID: executionID, limits: limits, ctx: ctx,
		projected: map[string]*projectedTool{}, children: map[string]map[string]bool{}, semaphore: make(chan struct{}, concurrency),
		mutationQueue: newCodeModeMutationQueue(), pending: map[*codePromise]bool{}, receipts: []ToolCallReceipt{},
	}
	used := map[string]bool{}
	for i := range registry.Entries {
		definition := &registry.Entries[i]
		if allowed != nil && !allowed[definition.Name] {
			continue
		}
		var base []string
		if strings.EqualFold(definition.Namespace, "mcp") {
			raw := definition.Name
			lower := strings.ToLower(raw)
			for _, prefix := range []string{"mcp_", "mcp-", "mcp:"} {
				if strings.HasPrefix(lower, prefix) {
					raw = raw[len(prefix):]
					break
