	return &codeModeMutationQueue{locks: map[string]*sync.Mutex{}}
}

func (q *codeModeMutationQueue) lockKeys(keys []string) func() {
	uniqueSet := map[string]bool{}
	for _, key := range keys {
		if key != "" {
			uniqueSet[key] = true
		}
	}
	unique := make([]string, 0, len(uniqueSet))
	for key := range uniqueSet {
		unique = append(unique, key)
	}
	sort.Strings(unique)
	locks := make([]*sync.Mutex, 0, len(unique))
	q.mu.Lock()
	for _, key := range unique {
		lock := q.locks[key]
		if lock == nil {
			lock = &sync.Mutex{}
			q.locks[key] = lock
		}
		locks = append(locks, lock)
	}
	q.mu.Unlock()
	for _, lock := range locks {
		lock.Lock()
	}
	return func() {
		for i := len(locks) - 1; i >= 0; i-- {
			locks[i].Unlock()
		}
	}
}

