func newCodeModeToolRuntime(ctx context.Context, registry *ToolRegistry, allowed map[string]bool, workspace, executionID string, limits CodeModeLimits) *codeModeToolRuntime {
	concurrency := limits.MaxConcurrentToolCalls
	if concurrency < 1 {
		concurrency = 1
	}
	r := &codeModeToolRuntime{
		registry: registry, allowed: allowed, workspace: workspace, executionID: executionID, limits: limits, ctx: ctx,
		projected: map[string]*projectedTool{}, children: map[string]map[string]bool{}, semaphore: make(chan struct{}, concurrency),
		mutationQueue: newCodeModeMutationQueue(), pending: map[*codePromise]bool{}, receipts: []ToolCallReceipt{},
	}
	used := map[string]bool{}
	for i := range registry.Entries {
		definition := &registry.Entries[i]
		if allowed != nil && !allowed[definition.Name] {
			continue
		}
		var base []string
		if strings.EqualFold(definition.Namespace, "mcp") {
			raw := definition.Name
			lower := strings.ToLower(raw)
			for _, prefix := range []string{"mcp_", "mcp-", "mcp:"} {
				if strings.HasPrefix(lower, prefix) {
					raw = raw[len(prefix):]
					break
				}
			}
			base = []string{"mcp", safeToolSegment(raw)}
		} else {
			base = []string{safeToolSegment(definition.Name)}
		}
		candidate := append([]string(nil), base...)
		suffix := 2
		for used[strings.Join(candidate, ".")] {
			candidate = append([]string(nil), base...)
			candidate[len(candidate)-1] = fmt.Sprintf("%s_%d", base[len(base)-1], suffix)
			suffix++
		}
		key := strings.Join(candidate, ".")
		used[key] = true
		projected := &projectedTool{definition: definition, path: candidate, expression: "tools." + key}
		r.projected[key] = projected
		for index := range candidate {
			parent := strings.Join(candidate[:index], ".")
			if r.children[parent] == nil {
				r.children[parent] = map[string]bool{}
			}
			r.children[parent][candidate[index]] = true
		}
	}
	if r.children[""] == nil {
		r.children[""] = map[string]bool{}
	}
	r.children[""]["$codemode"] = true
	r.children["$codemode"] = map[string]bool{"search": true}
	return r
}

func (r *codeModeToolRuntime) unavailableAllowedTool() string {
	if r.allowed == nil {
		return ""
	}
	for name := range r.allowed {
		if !r.allowed[name] {
			continue
		}
		found := false
		for _, tool := range r.projected {
			if tool.definition.Name == name {
				found = true
				break
			}
		}
		if !found {
			return name
		}
	}
	return ""
}

