func (r *codeModeToolRuntime) member(reference *toolReference, name string, node ast.Node) (*toolReference, error) {
	if blockedCodeModeMembers[name] {
		return nil, cmError("TypeError", fmt.Sprintf("Property '%s' is not available in Code Mode.", name), node)
	}
	next := append(append([]string(nil), reference.path...), name)
	key := strings.Join(next, ".")
	if r.projected[key] != nil || r.children[key] != nil || key == "$codemode.search" {
		return &toolReference{path: next}, nil
	}
	available := r.keys(reference)
	if len(available) > 8 {
		available = available[:8]
	}
	suggestions := []string{"Use tools.$codemode.search(...) for discovery."}
	if len(available) > 0 {
		suggestions = []string{fmt.Sprintf("Available here: %s. Use tools.$codemode.search(...) for discovery.", strings.Join(available, ", "))}
	}
	return nil, cmError("UnknownTool", "Unknown Code Mode capability tools."+key+".", node, suggestions...)
}

func (r *codeModeToolRuntime) call(reference *toolReference, args []any, node ast.Node) (*codePromise, error) {
	key := strings.Join(reference.path, ".")
	if key == "$codemode.search" {
		if len(args) > 1 {
			return nil, cmError("InvalidToolArguments", "tools.$codemode.search expects at most one input value.", node)
		}
		var input any = map[string]any{}
		if len(args) == 1 {
			input = args[0]
		}
		result, err := r.search(input, node)
		if err != nil {
			return nil, err
		}
		return resolvedCodePromise(internalizeData(result)), nil
	}
	tool := r.projected[key]
	if tool == nil {
		return nil, cmError("UnknownTool", "tools."+key+" is not callable.", node)
	}
	if len(args) != 1 {
		return nil, cmError("InvalidToolArguments", tool.expression+" expects exactly one input value.", node)
	}
	input, err := hostData(args[0], "Arguments for "+tool.expression)
	if err != nil {
		if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
			runtimeErr.Node = node
		}
		return nil, err
	}
	p := startCodePromise(func() (any, error) { return r.execute(tool, input) })
	r.track(p)
	return p, nil
}

func (r *codeModeToolRuntime) track(p *codePromise) {
	r.mu.Lock()
	r.pending[p] = true
	r.mu.Unlock()
	go func() { <-p.done; r.mu.Lock(); delete(r.pending, p); r.mu.Unlock() }()
}

func (r *codeModeToolRuntime) drain() {
	for {
		r.mu.Lock()
		pending := make([]*codePromise, 0, len(r.pending))
		for p := range r.pending {
			pending = append(pending, p)
		}
		r.mu.Unlock()
		if len(pending) == 0 {
			return
		}
		for _, p := range pending {
			<-p.done
		}
	}
}

func (r *codeModeToolRuntime) getReceipts() []ToolCallReceipt {
	r.mu.Lock()
	defer r.mu.Unlock()
	return append([]ToolCallReceipt(nil), r.receipts...)
}

