func codeModeDiagnosticFromError(err error) CodeModeDiagnostic {
	if runtimeErr, ok := err.(*codeModeRuntimeError); ok {
		return CodeModeDiagnostic{
			Kind:        runtimeErr.Kind,
			Message:     runtimeErr.Message,
			Location:    runtimeErr.Position,
			Suggestions: append([]string(nil), runtimeErr.Suggestions...),
		}
	}
	if thrown, ok := err.(*programThrow); ok {
		message := stringValue(thrown.value)
		if record, ok := thrown.value.(*codeObject); ok {
			if value, exists := record.props["message"]; exists {
				message = stringValue(value)
			}
		}
		return CodeModeDiagnostic{Kind: "ExecutionError", Message: "Uncaught: " + message}
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return CodeModeDiagnostic{Kind: "TimeoutExceeded", Message: "Code Mode execution timed out."}
	}
	if errors.Is(err, context.Canceled) {
		return CodeModeDiagnostic{Kind: "Cancelled", Message: "Code Mode execution was aborted."}
	}
	return CodeModeDiagnostic{Kind: "ExecutionError", Message: err.Error()}
}

