func (e *CodeModeExecutor) RunWithPayloads(source string, payloads map[string]string, overrides ...CodeModeLimits) CodeModeResult {
	id := executionID()
	limits := e.limits
	if len(overrides) > 0 {
		limits = mergeCodeModeLimits(limits, overrides[0])
	}
	if strings.TrimSpace(source) == "" {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "ParseError", Message: "Code Mode requires a non-empty program."}, nil, 0)
	}
	if len([]byte(source)) > limits.MaxCodeBytes {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "ParseError", Message: fmt.Sprintf("Code Mode source exceeded the %d-byte limit.", limits.MaxCodeBytes)}, nil, 0)
	}
	if len(payloads) > defaultPayloadCount {
		return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payloads exceeded the %d-item limit.", defaultPayloadCount)}, nil, 0)
	}
	payloadBytes := 0
	for key, value := range payloads {
		if strings.TrimSpace(key) == "" {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: "Code Mode payload keys must be non-empty."}, nil, 0)
		}
		if len([]byte(key)) > defaultPayloadKeyBytes {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payload key '%s' exceeded the %d-byte limit.", key, defaultPayloadKeyBytes)}, nil, 0)
		}
		if blockedCodeModeMembers[key] {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payload key '%s' is reserved.", key)}, nil, 0)
		}
		payloadBytes += len([]byte(key)) + len([]byte(value))
		if payloadBytes > limits.MaxPayloadBytes {
			return errorCodeModeResult(id, CodeModeDiagnostic{Kind: "InvalidToolArguments", Message: fmt.Sprintf("Code Mode payloads exceeded the %d-byte limit.", limits.MaxPayloadBytes)}, nil, 0)
		}
	}
	// Backward compatibility for older clients that still embed a complete
	// apply_patch envelope in a template literal. New callers should use the
	// opaque payloads sidecar so arbitrary text never enters JavaScript syntax.
	source = normalizeCodeModePatchTemplateLiterals(source)

	parsed, err := parseCodeModeProgram(source)
	if err != nil {
		return errorCodeModeResult(id, codeModeDiagnosticFromError(err), nil, 0)
	}

	ctx, cancel := context.WithTimeout(context.Background(), limits.Timeout)
	defer cancel()
	runtime := newCodeModeToolRuntime(ctx, e.Registry, e.Allowed, e.WorkspaceRoot, id, limits)
	if unavailable := runtime.unavailableAllowedTool(); unavailable != "" {
		diagnostic := CodeModeDiagnostic{Kind: "UnknownTool", Message: fmt.Sprintf("Code Mode allowed tool '%s' is unavailable in this registry.", unavailable)}
		return errorCodeModeResult(id, diagnostic, nil, 0)
	}

	interpreter := newCodeModeInterpreter(ctx, runtime, payloads, limits, parsed.fileSet)
	output, steps, runErr := interpreter.execute(parsed.statements)
	runtime.drain()
	toolCalls := runtime.getReceipts()
	if runErr != nil {
		return errorCodeModeResult(id, codeModeDiagnosticFromError(runErr), toolCalls, steps)
	}
	if ctx.Err() != nil {
		diagnostic := codeModeDiagnosticFromError(ctx.Err())
		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
			diagnostic.Message = fmt.Sprintf("Code Mode exceeded the %dms timeout.", limits.Timeout.Milliseconds())
		}
		return errorCodeModeResult(id, diagnostic, toolCalls, steps)
	}

	outputPresent := !isUndefined(output)
	truncated := false
	if outputPresent {
		encoded, encodeErr := json.Marshal(output)
		if encodeErr != nil {
			diagnostic := CodeModeDiagnostic{Kind: "TypeError", Message: "Code Mode returned non-serializable data: " + encodeErr.Error() + ". Await every tools.* call and return JSON-compatible data."}
			return errorCodeModeResult(id, diagnostic, toolCalls, steps)
		}
		if len(encoded) > limits.MaxOutputBytes {
			output = map[string]any{"message": fmt.Sprintf("Code Mode output exceeded the %d-byte limit. Return a smaller summary from the program.", limits.MaxOutputBytes)}
			truncated = true
		}
	} else {
		output = nil
	}

	failedCalls := 0
	for _, call := range toolCalls {
		if call.Status == "error" {
			failedCalls++
		}
	}
	summary := fmt.Sprintf("Code Mode V2 completed with %d tool call", len(toolCalls))
	if len(toolCalls) != 1 {
		summary += "s"
	}
	summary += "."
	if failedCalls > 0 {
		summary = fmt.Sprintf("Code Mode V2 completed after handling %d failed tool call", failedCalls)
		if failedCalls != 1 {
			summary += "s"
		}
		summary += "."
	}
	return CodeModeResult{
		Status:        "success",
		Summary:       summary,
		Output:        output,
		OutputPresent: outputPresent,
		ToolCalls:     toolCalls,
		ExecutionID:   id,
		Truncated:     truncated,
		Engine:        "v2",
		Steps:         steps,
	}
