func boolPtr(v bool) *bool { return &v }

func codeModePayloadsFromInput(value any) (map[string]string, error) {
	if value == nil {
		return nil, nil
	}
	raw, ok := value.(map[string]any)
	if !ok {
		return nil, fmt.Errorf("payloads must be an object whose values are strings")
	}
	payloads := make(map[string]string, len(raw))
	for key, value := range raw {
		text, ok := value.(string)
		if !ok {
			return nil, fmt.Errorf("payloads.%s must be a string", key)
		}
		payloads[key] = text
	}
	return payloads, nil
}

func workspaceFromMCPInput(input map[string]any) (string, error) {
	workspaceRaw, ok := input["workspace_path"].(string)
	if !ok || strings.TrimSpace(workspaceRaw) == "" || !filepath.IsAbs(strings.TrimSpace(workspaceRaw)) {
		return "", fmt.Errorf("workspace_path must be a non-empty absolute path")
	}
	return resolveWorkspace(workspaceRaw)
}

