func codeModeToToolResult(result CodeModeResult, workspace string) ToolResult {
	var outputBody string
	media := []MediaPayload{}
	if result.OutputPresent {
		if s, ok := result.Output.(string); ok {
			outputBody = s
		} else {
			outputBody = formatCodeModeOutput(result.Output, result.ToolCalls)
		}
	} else if len(result.ToolCalls) > 0 {
		parts := make([]string, 0, len(result.ToolCalls)+1)
		parts = append(parts, "Code Mode completed tool calls but returned no explicit value.")
		for _, call := range result.ToolCalls {
			text := fmt.Sprintf("%s (%s): %s", call.Name, call.Status, call.Summary)
			if strings.TrimSpace(call.Body) != "" {
				text += "\n" + call.Body
			}
			parts = append(parts, text)
		}
		outputBody = strings.Join(parts, "\n\n")
	}
	body := result.Summary
	if outputBody != "" {
		body += "\n\n" + outputBody
	}
	calls := make([]map[string]any, 0, len(result.ToolCalls))
	for _, call := range result.ToolCalls {
		media = append(media, call.Media...)
		item := map[string]any{
			"arguments":   call.Arguments,
			"duration_ms": call.DurationMS,
			"name":        call.Name,
			"status":      call.Status,
			"summary":     call.Summary,
		}
		compactCodeModeReceiptBody(item, call.Body)
		if call.Semantics != nil {
			item["semantics"] = call.Semantics
		}
		if call.Subject != nil {
			item["subject"] = call.Subject
		}
		calls = append(calls, item)
	}
	status := "success"
	if result.Status != "success" {
		status = "error"
	}
	r := ToolResult{
		Body:      body,
		Status:    status,
		Summary:   result.Summary,
		Subject:   &Subject{Kind: "code_mode", Path: workspace},
		Truncated: result.Truncated,
		Media:     media,
		Semantics: map[string]any{
			"execution_id":    result.ExecutionID,
			"operation":       "tcode_mode",
			"output_limited":  result.Truncated,
			"tool_call_count": len(result.ToolCalls),
			"tool_calls":      calls,
		},
	}
	return r
}

func toolResultMap(r ToolResult) map[string]any {
	b, _ := json.Marshal(r)
	var out map[string]any
	_ = json.Unmarshal(b, &out)
	return out
}

func mcpToolResult(r ToolResult) *mcp.CallToolResult {
	text := r.Summary
	if strings.TrimSpace(r.Body) != "" {
		text = r.Body
		if r.Status == "error" && r.Summary != r.Body {
			text = r.Summary + "\n" + r.Body
		}
	}
	content := []mcp.Content{&mcp.TextContent{Text: text}}
	for _, media := range r.Media {
		if media.Kind == "image" && len(media.Data) > 0 && strings.HasPrefix(media.MIMEType, "image/") {
			content = append(content, &mcp.ImageContent{Data: media.Data, MIMEType: media.MIMEType})
		}
	}
	return &mcp.CallToolResult{
		Content:           content,
		StructuredContent: structuredToolResultMap(r),
		IsError:           r.Status == "error",
	}
}

