	}
	mcp.AddTool[map[string]any, any](server, writeTool, func(ctx context.Context, req *mcp.CallToolRequest, input map[string]any) (*mcp.CallToolResult, any, error) {
		if !options.Scopes.Allows("planner:write") {
			return mcpToolResult(failure("Missing required scope: planner:write")), nil, nil
		}
		workspace, err := workspaceFromMCPInput(input)
		if err != nil {
			return mcpToolResult(failure(err.Error())), nil, nil
		}
		pathValue, err := requireString(input, "path", false)
		if err != nil {
			return mcpToolResult(failure("Invalid arguments for write: " + err.Error())), nil, nil
		}
		content, err := requireString(input, "content", true)
		if err != nil {
			return mcpToolResult(failure("Invalid arguments for write: " + err.Error())), nil, nil
		}
		result, err := (WriteService{}).Write(workspace, pathValue, content)
		if err != nil {
			return mcpToolResult(failure(err.Error())), nil, nil
		}
		return mcpToolResult(result), nil, nil
	})

	patchTool := &mcp.Tool{
