package tidecode

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const managedDir = ".tidecode"

func resolveWorkspace(root string) (string, error) {
	if strings.TrimSpace(root) == "" || !filepath.IsAbs(root) {
		return "", errors.New("workspace_path must be an absolute path")
	}
	abs, err := filepath.Abs(root)
	if err != nil {
		return "", err
	}
	st, err := os.Stat(abs)
	if err != nil {
		return "", fmt.Errorf("selected workspace is not accessible: %w", err)
	}
	if !st.IsDir() {
		return "", errors.New("selected workspace must be a directory")
	}
	real, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return "", err
	}
	return filepath.Clean(real), nil
}

func inside(root, candidate string) bool {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	return rel == "." || (rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel))
}

func privateRelative(root, candidate string) bool {
	rel, err := filepath.Rel(root, candidate)
	if err != nil {
		return false
	}
	if rel == "." {
		return false
	}
	for _, p := range strings.FieldsFunc(rel, func(r rune) bool { return r == '/' || r == '\\' }) {
		if strings.EqualFold(p, managedDir) {
			return true
		}
	}
	return false
}

func genericReadVisible(root, candidate string) bool {
	if !privateRelative(root, candidate) {
