	_ = os.WriteFile(filepath.Join(root, "README.md"), []byte("# Planner\n"), 0o644)
	_ = os.WriteFile(outside, []byte("outside secret\n"), 0o644)
	read := ReadService{}
	search := SearchService{}
	r, err := read.Read(root, "src/server.ts")
	if err != nil {
		t.Fatal(err)
	}
	if r.Status != "success" || !strings.Contains(r.Body, "1: export const answer = 42") {
		t.Fatalf("bad read: %#v", r)
	}
	l, err := search.List(root, ".")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(l.Body, "src/") || !strings.Contains(l.Body, "README.md") {
		t.Fatalf("bad list %q", l.Body)
	}
	g, err := search.Glob(root, ".", "**/*.ts")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(g.Body, "server.ts") {
		t.Fatalf("bad glob %q", g.Body)
	}
	gr, err := search.Grep(root, ".", "answer")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(gr.Body, "server.ts") {
		t.Fatalf("bad grep %q", gr.Body)
	}
	if _, err = read.Read(root, outside); err == nil || !strings.Contains(err.Error(), "outside the selected workspace") {
		t.Fatalf("expected outside error, got %v", err)
	}
	if _, err = read.Read(root, filepath.Join("..", "..", "outside.txt")); err == nil || !strings.Contains(err.Error(), "outside the selected workspace") {
		t.Fatalf("expected traversal error, got %v", err)
	}
	private := filepath.Join(root, ".tidecode", "memory", "folders", "x", "y.md")
	if _, err = read.Read(root, private); err == nil || !strings.Contains(strings.ToLower(err.Error()), "private") {
