func TestExplorerSearchesAgentsAndReadablePlans(t *testing.T) {
	root := tempWorkspace(t)
	if err := os.MkdirAll(filepath.Join(root, ".tidecode", "plans"), 0o755); err != nil {
		t.Fatal(err)
	}
	for name := range map[string]string{
		"AGENTS.md": "visible agents\n",
		filepath.Join(".tidecode", "plans", "plan-001.md"): "visible plan\n",
		filepath.Join(".tidecode", "private.md"):           "visible private\n",
	} {
		if err := os.WriteFile(filepath.Join(root, name), []byte(map[string]string{
			"AGENTS.md": "visible agents\n",
			filepath.Join(".tidecode", "plans", "plan-001.md"): "visible plan\n",
			filepath.Join(".tidecode", "private.md"):           "visible private\n",
		}[name]), 0o644); err != nil {
			t.Fatal(err)
		}
	}
	reader := ReadService{}
	plan, err := reader.Read(root, ".tidecode/plans/plan-001.md")
	if err != nil || !strings.Contains(plan.Body, "visible plan") {
		t.Fatalf("plan should be readable: %#v, %v", plan, err)
	}
	managed, err := reader.Read(root, ".tidecode")
	if err != nil || !strings.Contains(managed.Body, "plans/") || strings.Contains(managed.Body, "private.md") {
		t.Fatalf(".tidecode listing should expose plans only: %#v, %v", managed, err)
	}
	if _, err := reader.Read(root, ".tidecode/private.md"); err == nil || !strings.Contains(strings.ToLower(err.Error()), "private") {
		t.Fatalf("private managed file should stay unreadable: %v", err)
	}

	svc := SearchService{}
	listed, err := svc.List(root, ".")
	if err != nil || !strings.Contains(listed.Body, "AGENTS.md") || !strings.Contains(listed.Body, ".tidecode/") {
		t.Fatalf("list should include filtered names: %#v, %v", listed, err)
	}
	globbed, err := svc.Glob(root, ".", "**/*")
	if err != nil || !strings.Contains(globbed.Body, "AGENTS.md") || !strings.Contains(globbed.Body, ".tidecode/plans/plan-001.md") || strings.Contains(globbed.Body, ".tidecode/private.md") {
		t.Fatalf("glob should include filtered names: %#v, %v", globbed, err)
	}
	grepped, err := svc.Grep(root, ".", "visible")
	if err != nil || !strings.Contains(grepped.Body, "AGENTS.md") || !strings.Contains(grepped.Body, ".tidecode/plans/plan-001.md") || strings.Contains(grepped.Body, ".tidecode/private.md") {
		t.Fatalf("grep should include filtered names: %#v, %v", grepped, err)
	}
}

