		if !strings.Contains(desc, needle) {
			t.Fatalf("description missing %q", needle)
		}
		if strings.Contains(desc, "tools.write(") || strings.Contains(desc, "tools.apply_patch(") {
			t.Fatalf("direct mutation tools leaked into Code Mode description: %s", desc)
		}
		for _, mutation := range []*mcp.Tool{byName["write"], byName["apply_patch"]} {
			if !strings.Contains(mutation.Description, "read") && !strings.Contains(mutation.Description, "readability") {
				t.Fatalf("mutation description missing human-readable source guidance: %s", mutation.Description)
			}
		}
	}
	for _, needle := range []string{"Node.js globals and modules", "`process`", "`require`", "`fs` / `node:fs`", "`child_process`", "rejected before tool execution"} {
		if !strings.Contains(desc, needle) {
			t.Fatalf("description missing runtime contract %q", needle)
		}
	}
	patchDescription := byName["apply_patch"].Description
	for _, needle := range []string{"Use *** Add File only for a new path", "every file-content line in an Add File hunk must start with +", "Use *** Update File for edits to an existing path"} {
		if !strings.Contains(patchDescription, needle) {
			t.Fatalf("apply_patch description missing %q: %s", needle, patchDescription)
		}
	}
	if strings.Contains(desc, "tools.execute_terminal({ command, wait_seconds") {
		t.Fatalf("execute signature includes wait_seconds: %s", desc)
	}
	if tool.Annotations == nil || tool.Annotations.ReadOnlyHint || tool.Annotations.DestructiveHint == nil || !*tool.Annotations.DestructiveHint {
		t.Fatalf("annotations %#v", tool.Annotations)
	}
	patch := "*** Begin Patch\n*** Update File: src/created.ts\n@@\n-const created = true\n+const created = false\n*** End Patch"
