		t.Fatalf("direct write failed: %v %s", err, mcpText(writeResult))
	}
	patchResult, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "apply_patch", Arguments: map[string]any{"workspace_path": root, "patch": patch}})
	if err != nil || patchResult.IsError {
		t.Fatalf("direct patch failed: %v %s", err, mcpText(patchResult))
	}
	delimiterHeavy := strings.Join([]string{
		"```tsx",
		"const view = `hello ${name}`",
		`const path = "C:\\Users\\Admin\\file.ts"`,
		"```",
		"",
	}, "\n")
	heavyWrite, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "write", Arguments: map[string]any{"workspace_path": root, "path": "src/nested.md", "content": delimiterHeavy}})
	if err != nil || heavyWrite.IsError {
		t.Fatalf("delimiter-heavy direct write failed: %v %s", err, mcpText(heavyWrite))
	}
	heavyPatch := "*** Begin Patch\n*** Update File: src/nested.md\n@@\n-const view = `hello ${name}`\n+const view = `hi ${name}`\n*** End Patch"
	heavyPatched, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "apply_patch", Arguments: map[string]any{"workspace_path": root, "patch": heavyPatch}})
	if err != nil || heavyPatched.IsError {
		t.Fatalf("delimiter-heavy direct patch failed: %v %s", err, mcpText(heavyPatched))
	}
	heavyBytes, err := os.ReadFile(filepath.Join(root, "src", "nested.md"))
	if err != nil {
		t.Fatal(err)
	}
	if string(heavyBytes) != strings.Replace(delimiterHeavy, "hello ${name}", "hi ${name}", 1) {
		t.Fatalf("delimiter-heavy mutation changed payload unexpectedly: %q", heavyBytes)
	}
	code := strings.Join([]string{
		"const read = await tools.read({ path: 'src/protocol.ts' })",
		"const glob = await tools.glob({ path: '.', pattern: '**/*.ts' })",
		"const grep = await tools.grep({ path: '.', pattern: 'planner' })",
		"const list = await tools.list({ path: '.' })",
		"const plan = await tools.plan_create({ title: 'Protocol plan', content: '## Steps\\n\\n1. Inspect the current flow.' })",
		"await tools.memory({ action: 'write', folder: 'protocol', name: 'note', title: 'Protocol note', content: 'Planner evidence.' })",
		"const memory = await tools.memory({ action: 'read', folder: 'protocol', name: 'note' })",
		"const search = await tools.tool_search({ query: 'search workspace contents' })",
		"return { read: read.status, glob: glob.status, grep: grep.status, list: list.status, plan: plan.status, memory: memory.status, search: search.status }",
	}, "\n")
	r, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": code}})
	if err != nil {
		t.Fatal(err)
	}
	if r.IsError {
		t.Fatalf("tool error: %s", mcpText(r))
	}
	if !strings.Contains(mcpText(r), `"read": "success"`) || !strings.Contains(mcpText(r), `"search": "success"`) {
		t.Fatalf("text %s", mcpText(r))
	}
	for _, unavailable := range []string{"write", "apply_patch"} {
		got, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": "return await tools." + unavailable + "({})"}})
		if err != nil {
			t.Fatal(err)
		}
		registryTerminal := NewTerminalService()
		defer registryTerminal.Close()
		registry := bindCodeModeRegistry(root, "mcp-registry-test", registryTerminal, nil)
		if registry.Get("write") != nil || registry.Get("apply_patch") != nil {
			t.Fatalf("direct mutation tools remained in Code Mode registry")
		}
		for _, match := range registry.Search("write patch file") {
			if match.Name == "write" || match.Name == "apply_patch" {
				t.Fatalf("direct mutation tool leaked through Code Mode search: %s", match.Name)
			}
		}
		if !got.IsError || !strings.Contains(mcpText(got), "Unknown Code Mode capability") {
			t.Fatalf("inner %s unexpectedly available: %s", unavailable, mcpText(got))
		}
	}
	b, _ := os.ReadFile(filepath.Join(root, "src", "created.ts"))
	if string(b) != "const created = false\n" {
		t.Fatalf("created %q", b)
	}
	b, _ = os.ReadFile(filepath.Join(root, ".tidecode", "memory", "folders", "protocol", "note.md"))
	if string(b) != "# Protocol note\n\nPlanner evidence.\n" {
		t.Fatalf("memory %q", b)
	}
	b, _ = os.ReadFile(filepath.Join(root, ".tidecode", "plans", "plan-001.md"))
	if !strings.Contains(string(b), "# Protocol plan") {
		t.Fatalf("plan %q", b)
	}
	blocked, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": "return process.version"}})
	if err != nil {
		t.Fatal(err)
	}
	if !blocked.IsError || !strings.Contains(mcpText(blocked), "process is not defined") {
		t.Fatalf("blocked %s", mcpText(blocked))
	}
	bypass := filepath.Join(root, "src", "runtime-bypass.txt")
	blocked, err = session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": "require('node:fs').writeFileSync('src/runtime-bypass.txt', 'unsafe')"}})
	if err != nil {
		t.Fatal(err)
	}
	if !blocked.IsError {
		t.Fatalf("require not blocked: %s", mcpText(blocked))
	}
	if _, err := os.Stat(bypass); !os.IsNotExist(err) {
		t.Fatalf("bypass exists: %v", err)
	}
}

