		t.Fatalf("memory %q", b)
	}
	b, _ = os.ReadFile(filepath.Join(root, ".tidecode", "plans", "plan-001.md"))
	if !strings.Contains(string(b), "# Protocol plan") {
		t.Fatalf("plan %q", b)
	}
	blocked, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": "return process.version"}})
	if err != nil {
