	r, err := session.CallTool(context.Background(), &mcp.CallToolParams{Name: "tcode_mode", Arguments: map[string]any{"workspace_path": root, "code": code}})
	if err != nil {
		t.Fatal(err)
	}
	if r.IsError {
		t.Fatalf("image tool error: %s", mcpText(r))
	}
	var imageContent *mcp.ImageContent
	for _, content := range r.Content {
		if image, ok := content.(*mcp.ImageContent); ok {
			imageContent = image
			break
		}
	}
	if imageContent == nil {
		t.Fatalf("missing MCP image content: %#v", r.Content)
	}
	if imageContent.MIMEType != "image/png" || len(imageContent.Data) == 0 {
		t.Fatalf("image content %#v", imageContent)
	}
	if _, _, err := image.DecodeConfig(bytes.NewReader(imageContent.Data)); err != nil {
		t.Fatalf("invalid returned image bytes: %v", err)
	}
	structured, err := json.Marshal(r.StructuredContent)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(structured), "iVBOR") {
		t.Fatalf("image bytes leaked into structured content")
	}
}

