{
  "body": "Code Mode V2 completed with 1 tool call.

package tidecode

import (
	"encoding/json"
	"fmt"
	"sort"
	"strings"
)

type ScopeSet map[string]bool

func (s ScopeSet) Allows(scope string) bool { return s == nil || s[scope] }

type ToolDefinition struct {
	Name, Title, Description, Namespace, Scope, Signature string
	Execute                                               func(map[string]any) (ToolResult, error)
	ExecuteRaw                                            func(string) (ToolResult, error)
}
type ToolRegistry struct {
	Entries []ToolDefinition
	byName  map[string]*ToolDefinition
}

func newRegistry(entries []ToolDefinition) *ToolRegistry {
	r := &ToolRegistry{Entries: entries, byName: map[string]*ToolDefinition{}}
	for i := range r.Entries {
		r.byName[r.Entries[i].Name] = &r.Entries[i]
	}
	return r
}
func (r *ToolRegistry) Get(name string) *ToolDefinition { return r.byName[name] }
func toolSearchScore(d ToolDefinition, tokens []string) int {
	name := strings.ToLower(d.Name)
	namespace := strings.ToLower(d.Namespace)
	description := strings.ToLower(d.Description)
	score := 0
	for _, token := range tokens {
		if name == token {
			score += 100
		} else if strings.Contains(name, token) {
			score += 50
		}
		if namespace == token {
			score += 30
		} else if strings.Contains(namespace, token) {
			score += 15
		}
		if strings.Contains(description, token) {
			score += 10
		}
	}
	return score
}

func (r *ToolRegistry) SearchWithOptions(query, namespace string, limit int) []ToolDefinition {
	normalizedQuery := strings.ToLower(strings.TrimSpace(query))
	tokens := strings.Fields(normalizedQuery)
	normalizedNamespace := strings.ToLower(strings.TrimSpace(namespace))
	if limit <= 0 {
		limit = 10
	}
	if limit > 20 {
		limit = 20
	}
	type scored struct {
		d ToolDefinition
		n int
	}
	hits := []scored{}
	for _, d := range r.Entries {
		if d.Name == "tool_search" {
			continue
		}
		if normalizedNamespace != "" && strings.ToLower(d.Namespace) != normalizedNamespace {
			continue
		}
		score := toolSearchScore(d, tokens)
		if normalizedNamespace != "" {
			score += 1000
		}
		if normalizedQuery == "" || score > 0 {
			hits = append(hits, scored{d: d, n: score})
		}
	}
	sort.SliceStable(hits, func(i, j int) bool {
		if hits[i].n == hits[j].n {
			return hits[i].d.Name < hits[j].d.Name
		}
		return hits[i].n > hits[j].n
	})
	if len(hits) > limit {
		hits = hits[:limit]
	}
	out := make([]ToolDefinition, len(hits))
	for i, hit := range hits {
		out[i] = hit.d
	}
	return out
}

func (r *ToolRegistry) Search(query string) []ToolDefinition {
	return r.SearchWithOptions(query, "", 20)
}

func decodeMap(m map[string]any, out any) error {
	b, err := json.Marshal(m)
	if err != nil {
		return err
	}
	return json.Unmarshal(b, out)
}
func numInt(v any) int {
	switch x := v.(type) {
	case int:
		return x
	case int64:
		return int(x)
	case float64:
		return int(x)
	case json.Number:
		n, _ := x.Int64()
		return int(n)
	}
	return 0
}
func requireString(m map[string]any, key string, allowEmpty bool) (string, error) {
	v, ok := m[key]
	if !ok {
		return "", fmt.Errorf("%s is required", key)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("%s must be a string", key)
	}
	if !allowEmpty && strings.TrimSpace(s) == "" {
		return "", fmt.Errorf("%s must be non-empty", key)
	}
	return s, nil
}

