	add(ToolDefinition{Name: "write", Title: "Write", Namespace: "workspace", Scope: "planner:write", Signature: "tools.write({ path, content })", Description: "Create or overwrite a workspace text file. The path must be non-empty. Complex multiline source may be supplied with triple quotes so Code Mode can normalize it safely; quotes inside triple-quoted source do not need manual escaping, and one redundant generated escaping layer on every matching quote delimiter is removed conservatively.", Execute: func(m map[string]any) (ToolResult, error) {
