const maxMutationBytes = 10 << 20
const maxEdits = 20

var mutationLocks sync.Map

func mutationLockKey(path string) string {
	key := filepath.Clean(path)
	if runtime.GOOS == "windows" {
		key = strings.ToLower(key)
	}
	return key
}

func mutationLock(path string) *sync.Mutex {
	v, _ := mutationLocks.LoadOrStore(mutationLockKey(path), &sync.Mutex{})
	return v.(*sync.Mutex)
}

type WriteService struct{}

func (WriteService) Write(root, path, content string) (ToolResult, error) {
	target, err := resolveMutationPath(root, path)
	if err != nil {
		return ToolResult{}, err
	}
	if len(content) > maxMutationBytes {
		return failure("content exceeds 10 MiB mutation limit"), nil
	}
	mu := mutationLock(target)
	mu.Lock()
	defer mu.Unlock()
	content = normalizeText(content)
	old, readErr := os.ReadFile(target)
	if readErr == nil && string(old) == content {
		r := withSubject(success("No changes to "+filepath.ToSlash(path)), "file", filepath.ToSlash(path))
		r.Semantics = map[string]any{"operation": "noop", "changed_paths": []string{}}
		return r, nil
	}
	if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
		return ToolResult{}, err
	}
	op := "create"
	if readErr == nil {
		op = "overwrite"
	}
	if err := os.WriteFile(target, []byte(content), 0o644); err != nil {
		return ToolResult{}, err
	}
	workspace, _ := resolveWorkspace(root)
	rel := slashRelative(workspace, target)
	r := withSubject(withBody(success(strings.Title(op)+"d "+rel), fmt.Sprintf("%s: %s", op, rel)), "file", rel)
	r.Semantics = map[string]any{"operation": op, "changed_paths": []string{rel}, "updated_path_count": 1}
	return r, nil
}

type EditHunk struct {
	TargetContent      string `json:"targetContent"`
	ReplacementContent string `json:"replacementContent"`
	AllowMultiple      *bool  `json:"allowMultiple,omitempty"`
	ReplaceAll         *bool  `json:"replaceAll,omitempty"`
	StartLine          int    `json:"startLine,omitempty"`
	EndLine            int    `json:"endLine,omitempty"`
}

type EditService struct{}

type textRange struct {
	start, end         int
	lineStart, lineEnd int
}

type lineSegment struct {
	start, end   int
	hasLineBreak bool
	text         string
}

type resolvedReplacement struct {
	chunkIndex  int
	start, end  int
	replacement string
}

func exactRanges(content, target string) []textRange {
	if target == "" {
		return nil
	}
	matches := []textRange{}
	searchOffset := 0
	for searchOffset <= len(content)-len(target) {
		rel := strings.Index(content[searchOffset:], target)
		if rel < 0 {
			break
		}
		start := searchOffset + rel
		end := start + len(target)
		matches = append(matches, textRange{
			start:     start,
			end:       end,
			lineStart: 1 + strings.Count(content[:start], "\n"),
			lineEnd:   1 + strings.Count(content[:maxInt(start, end-1)], "\n"),
		})
		searchOffset = end
	}
	return matches
}

func getLineSegments(content string) []lineSegment {
	segments := []lineSegment{}
	start := 0
	for start <= len(content) {
		rel := strings.Index(content[start:], "\n")
		if rel < 0 {
			segments = append(segments, lineSegment{start: start, end: len(content), text: content[start:]})
			break
		}
		newline := start + rel
		segments = append(segments, lineSegment{start: start, end: newline + 1, hasLineBreak: true, text: content[start:newline]})
		start = newline + 1
	}
	return segments
}

var horizontalWhitespaceRx = regexp.MustCompile(`[\t ]+`)
var escapedPunctuationRx = regexp.MustCompile(`\\([^\w\s])`)
var keyTokenSplitRx = regexp.MustCompile(`[^a-zA-Z0-9_$]`)

func normalizeLineWhitespace(line string) string {
	return strings.TrimSpace(strings.ReplaceAll(line, "\r", ""))
}

func normalizeLineWhitespaceCollapsed(line string) string {
	return horizontalWhitespaceRx.ReplaceAllString(normalizeLineWhitespace(line), " ")
}

func normalizeBackslashes(line string) string {
	return strings.ReplaceAll(line, `\\`, `\`)
}

func normalizeEscapedPunctuation(line string) string {
	return escapedPunctuationRx.ReplaceAllString(line, "$1")
}

func linesMatchTolerantly(contentLine, targetLine string, first, last bool) bool {
	cNorm := normalizeLineWhitespace(contentLine)
	tNorm := normalizeLineWhitespace(targetLine)
	if cNorm == tNorm || normalizeLineWhitespaceCollapsed(contentLine) == normalizeLineWhitespaceCollapsed(targetLine) {
		return true
	}
	if normalizeBackslashes(cNorm) == normalizeBackslashes(tNorm) || normalizeBackslashes(normalizeLineWhitespaceCollapsed(contentLine)) == normalizeBackslashes(normalizeLineWhitespaceCollapsed(targetLine)) {
		return true
	}
	cPunct := normalizeEscapedPunctuation(cNorm)
	tPunct := normalizeEscapedPunctuation(tNorm)
	if cPunct == tPunct || normalizeLineWhitespaceCollapsed(cPunct) == normalizeLineWhitespaceCollapsed(tPunct) {
		return true
	}
	if first && (strings.HasSuffix(cNorm, tNorm) || strings.HasSuffix(cPunct, tPunct)) {
		return true
	}
	if last && (strings.HasPrefix(cNorm, tNorm) || strings.HasPrefix(cPunct, tPunct)) {
		return true
	}
	return false
}

func tolerantRanges(content, target string) []textRange {
	contentSegments := getLineSegments(content)
	targetSegments := getLineSegments(target)
	hasTerminalLineBreak := strings.HasSuffix(target, "\n")
	if hasTerminalLineBreak && len(targetSegments) > 0 {
		targetSegments = targetSegments[:len(targetSegments)-1]
	}
	if len(targetSegments) == 0 {
		return nil
	}
	matches := []textRange{}
	for startIndex := 0; startIndex <= len(contentSegments)-len(targetSegments); startIndex++ {
		ok := true
		for targetIndex, targetLine := range targetSegments {
			contentLine := contentSegments[startIndex+targetIndex].text
			if !linesMatchTolerantly(contentLine, targetLine.text, targetIndex == 0, targetIndex == len(targetSegments)-1) {
				ok = false
				break
			}
		}
		if !ok {
			continue
		}
		first := contentSegments[startIndex]
		last := contentSegments[startIndex+len(targetSegments)-1]
		end := last.end
		if !hasTerminalLineBreak && last.hasLineBreak {
			end--
		}
		matches = append(matches, textRange{start: first.start, end: end, lineStart: startIndex + 1, lineEnd: startIndex + len(targetSegments)})
	}
	return matches
}

func extractKeyTokens(value string) []string {
	parts := keyTokenSplitRx.Split(value, -1)
	tokens := make([]string, 0, len(parts))
	for _, part := range parts {
		if len(part) > 1 {
			tokens = append(tokens, part)
		}
	}
	return tokens
}

func fuzzyRanges(content, target string) []textRange {
	contentSegments := getLineSegments(content)
	targetSegments := getLineSegments(target)
	hasTerminalLineBreak := strings.HasSuffix(target, "\n")
	if hasTerminalLineBreak && len(targetSegments) > 0 {
		targetSegments = targetSegments[:len(targetSegments)-1]
	}
	if len(targetSegments) == 0 {
		return nil
	}
	targetTokens := extractKeyTokens(target)
	if len(targetTokens) == 0 {
		return nil
	}
	bestScore := 0.0
	var best *textRange
	for startIndex := 0; startIndex <= len(contentSegments)-len(targetSegments); startIndex++ {
		window := contentSegments[startIndex : startIndex+len(targetSegments)]
		parts := make([]string, len(window))
		for i, segment := range window {
			parts[i] = segment.text
		}
		windowTokenSet := map[string]bool{}
		for _, token := range extractKeyTokens(strings.Join(parts, "\n")) {
			windowTokenSet[token] = true
		}
		matchCount := 0
		for _, token := range targetTokens {
			if windowTokenSet[token] {
				matchCount++
			}
		}
		score := float64(matchCount) / float64(len(targetTokens))
		if score > 0.65 && score > bestScore {
			bestScore = score
			first := window[0]
			last := window[len(window)-1]
			end := last.end
			if !hasTerminalLineBreak && last.hasLineBreak {
				end--
			}
			r := textRange{start: first.start, end: end, lineStart: startIndex + 1, lineEnd: startIndex + len(targetSegments)}
			best = &r
		}
	}
	if best == nil {
		return nil
	}
	return []textRange{*best}
}

func lineRangeOffsets(content string, startLine, endLine int) (int, int, error) {
	lines := strings.Split(content, "\n")
	totalLines := len(lines)
	if startLine < 1 || endLine < startLine || endLine > totalLines {
		return 0, 0, fmt.Errorf("invalid line range [%d, %d] (%d lines total)", startLine, endLine, totalLines)
	}
	startOffset := 0
	for i := 0; i < startLine-1; i++ {
		startOffset += len(lines[i]) + 1
	}
	endOffset := startOffset
	for i := startLine - 1; i < endLine; i++ {
		endOffset += len(lines[i])
		if i < endLine-1 || endLine < totalLines {
			endOffset++
		}
	}
	return startOffset, endOffset, nil
}

func resolveHunkRanges(content string, h EditHunk, displayPath string, chunkIndex int) ([]resolvedReplacement, error) {
	target := h.TargetContent
	if strings.HasSuffix(target, "\n") {
		target = strings.TrimSuffix(target, "\n")
	}
	matches := exactRanges(content, target)
	if len(matches) == 0 {
		matches = tolerantRanges(content, target)
	}
	if len(matches) == 0 {
		matches = fuzzyRanges(content, target)
	}
	if len(matches) == 0 {
		if h.StartLine > 0 {
			return nil, fmt.Errorf("Target content not found between lines %d and %d in %q.", h.StartLine, h.EndLine, displayPath)
		}
		return nil, fmt.Errorf("Target content not found in %q. Verify the target text and retry with the exact current text.", displayPath)
	}
	if h.StartLine > 0 {
		rangeStart, rangeEnd, err := lineRangeOffsets(content, h.StartLine, h.EndLine)
		if err != nil {
			return nil, fmt.Errorf("Invalid line range [%d, %d] for file %q: %w", h.StartLine, h.EndLine, displayPath, err)
		}
		filtered := matches[:0]
		for _, match := range matches {
			if match.start >= rangeStart && match.end <= rangeEnd {
				filtered = append(filtered, match)
			}
		}
		matches = filtered
		if len(matches) == 0 {
			return nil, fmt.Errorf("Target content not found between lines %d and %d in %q.", h.StartLine, h.EndLine, displayPath)
		}
	}
	replaceAll := true
	if h.ReplaceAll != nil {
		replaceAll = *h.ReplaceAll
	} else if h.AllowMultiple != nil {
		replaceAll = *h.AllowMultiple
	}
	if len(matches) > 1 && !replaceAll {
		parts := make([]string, 0, len(matches))
		seen := map[string]bool{}
		for _, match := range matches {
			label := fmt.Sprintf("%d-%d", match.lineStart, match.lineEnd)
			if !seen[label] {
				seen[label] = true
				parts = append(parts, label)
			}
		}
		rangeDescription := ""
		if h.StartLine > 0 {
			rangeDescription = fmt.Sprintf(" between lines %d and %d", h.StartLine, h.EndLine)
		}
		return nil, fmt.Errorf("Target content found %d times%s in %q. Candidate line ranges: %s.", len(matches), rangeDescription, displayPath, strings.Join(parts, ", "))
	}
	replacement := h.ReplacementContent
	if strings.HasSuffix(replacement, "\n") {
		replacement = strings.TrimSuffix(replacement, "\n")
	}
	resolved := make([]resolvedReplacement, 0, len(matches))
	for _, match := range matches {
		resolved = append(resolved, resolvedReplacement{chunkIndex: chunkIndex, start: match.start, end: match.end, replacement: replacement})
	}
	return resolved, nil
}

func applyResolvedReplacements(content string, replacements []resolvedReplacement) string {
	sort.SliceStable(replacements, func(i, j int) bool {
		if replacements[i].start == replacements[j].start {
			return replacements[i].end < replacements[j].end
		}
		return replacements[i].start < replacements[j].start
	})
	nonOverlapping := make([]resolvedReplacement, 0, len(replacements))
	for _, current := range replacements {
		if len(nonOverlapping) == 0 || current.start >= nonOverlapping[len(nonOverlapping)-1].end {
			nonOverlapping = append(nonOverlapping, current)
		}
	}
	updated := content
	for i := len(nonOverlapping) - 1; i >= 0; i-- {
		r := nonOverlapping[i]
		updated = updated[:r.start] + r.replacement + updated[r.end:]
	}
	return updated
}

func normalizeEditHunks(edits []EditHunk) ([]EditHunk, error) {
	if len(edits) == 0 || len(edits) > maxEdits {
		return nil, fmt.Errorf("edits must contain between 1 and %d hunks", maxEdits)
	}
	normalized := make([]EditHunk, 0, len(edits))
	changed := make([]EditHunk, 0, len(edits))
	for idx, h := range edits {
		if h.TargetContent == "" {
			return nil, fmt.Errorf("Edit hunk %d requires non-empty targetContent.", idx+1)
		}
		if (h.StartLine == 0) != (h.EndLine == 0) {
