const maxTranscriptChars = 300000
const terminalCompletionSettle = 100 * time.Millisecond
const terminalReapInterval = 30 * time.Second
const completedTerminalRetention = 2 * time.Minute
const activeTerminalIdleTimeout = 30 * time.Minute

type TerminalExecuteInput struct {
	Command       string `json:"command"`
	Cwd           string `json:"cwd,omitempty"`
	WorkspacePath string `json:"workspace_path,omitempty"`
}
type TerminalReadInput struct {
	SessionID     int    `json:"session_id"`
