type terminalSession struct {
	mu              sync.Mutex
	id              int
	owner           string
	workspace       string
	pty             ptylib.Pty
	cmd             *ptylib.Cmd
	lines           []string
	partial         string
	unread          int
	state           string
	exitStatus      string
	startMarker     string
	marker          string
	started         bool
	lastActivity    time.Time
	closed          bool
	resourcesClosed bool
	onComplete      func(*terminalSession)
}

type TerminalService struct {
	mu       sync.Mutex
	sessions map[int]*terminalSession
	next     int
	closed   bool
	stopCh   chan struct{}
	doneCh   chan struct{}
}

func NewTerminalService() *TerminalService {
	s := &TerminalService{
		sessions: map[int]*terminalSession{},
		next:     10000,
		stopCh:   make(chan struct{}),
		doneCh:   make(chan struct{}),
	}
	go s.reapLoop()
	return s
}

func (s *terminalSession) closeResources(killProcess bool) {
	s.mu.Lock()
	if s.resourcesClosed {
		s.mu.Unlock()
		return
	}
	s.resourcesClosed = true
	cmd := s.cmd
	pty := s.pty
	s.mu.Unlock()

	if killProcess && cmd != nil && cmd.Process != nil {
		_ = cmd.Process.Kill()
	}
	if pty != nil {
		_ = pty.Close()
	}
}

func (s *TerminalService) reapLoop() {
	ticker := time.NewTicker(terminalReapInterval)
	defer ticker.Stop()
	defer close(s.doneCh)
	for {
		select {
		case now := <-ticker.C:
			s.reapTerminalSessions(now)
		case <-s.stopCh:
			return
		}
	}
}

func (s *TerminalService) reapTerminalSessions(now time.Time) {
	stale := make([]*terminalSession, 0)
	s.mu.Lock()
	for id, session := range s.sessions {
		session.mu.Lock()
		state := session.state
		lastActivity := session.lastActivity
		session.mu.Unlock()

		completedExpired := state == "completed" && now.Sub(lastActivity) >= completedTerminalRetention
		activeExpired := state != "completed" && now.Sub(lastActivity) >= activeTerminalIdleTimeout
		if completedExpired || activeExpired {
			delete(s.sessions, id)
			stale = append(stale, session)
		}
	}
	s.mu.Unlock()

	for _, session := range stale {
		session.closeResources(true)
	}
}

func (s *TerminalService) removeSession(id int, expected *terminalSession) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	current := s.sessions[id]
	if current == nil || (expected != nil && current != expected) {
		return false
	}
	delete(s.sessions, id)
	return true
}

func shellCandidate() (string, []string, string, error) {
	if runtime.GOOS == "windows" {
		for _, name := range []string{"pwsh.exe", "pwsh", "powershell.exe", "powershell"} {
			if p, err := exec.LookPath(name); err == nil {
				return p, []string{"-NoLogo", "-NoProfile", "-NoExit"}, "powershell", nil
			}
		}
		if p, err := exec.LookPath("cmd.exe"); err == nil {
			return p, []string{"/Q"}, "cmd", nil
		}
		return "", nil, "", errors.New("no supported Windows shell found")
	}
	for _, name := range []string{os.Getenv("SHELL"), "zsh", "bash", "sh"} {
		if name == "" {
			continue
		}
		if p, err := exec.LookPath(name); err == nil {
			return p, []string{}, "unix", nil
		}
	}
	return "", nil, "", errors.New("no supported shell found")
}

func (s *TerminalService) allocate() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	for i := 0; i < 90000; i++ {
		s.next++
		if s.next > 99999 {
			s.next = 10000
		}
		if _, ok := s.sessions[s.next]; !ok {
			return s.next
		}
	}
	return 0
}

