			if stringEscape {
				if r == '\\' {
					stringControl = false
				}
				stringEscape = false
				continue
			}
			if r == 0x07 {
				stringControl = false
				continue
			}
			if r == 0x1b {
				stringEscape = true
			}
			continue
		}
		if esc {
			esc = false
			if r == '[' {
				csi = true
				continue
			}
			if r == ']' || r == 'P' || r == '^' || r == '_' {
				stringControl = true
				continue
			}
			continue
		}
		if csi {
			if r >= 0x40 && r <= 0x7e {
				csi = false
			}
			continue
