		n := e.Name()
		if e.IsDir() {
			n += "/"
		}
		items = append(items, n)
	}
	sort.Slice(items, func(i, j int) bool { return strings.ToLower(items[i]) < strings.ToLower(items[j]) })
	paged, off, end := pageStrings(items, opts...)
	body := "Empty directory"
	if len(paged) > 0 {
