	}
	return r, nil
}

func (SearchService) Glob(root, path, pattern string, opts ...SearchOptions) (ToolResult, error) {
	target, err := resolveReadPath(root, path, true)
	if err != nil {
		return ToolResult{}, err
	}
	matches := []string{}
	workspace, _ := resolveWorkspace(root)
	st, err := os.Stat(target)
	if err != nil {
		return ToolResult{}, err
	}
	if !st.IsDir() {
		rel := filepath.ToSlash(mustRel(target, target))
		ok, _ := doublestar.Match(pattern, filepath.Base(rel))
		if ok {
			matches = append(matches, filepath.ToSlash(mustRel(workspace, target)))
		}
	} else {
		_ = walkVisible(workspace, target, func(p string, d os.DirEntry) bool {
			if d.IsDir() {
				return true
			}
			rel := filepath.ToSlash(mustRel(target, p))
			ok, _ := doublestar.Match(pattern, rel)
			if ok {
				matches = append(matches, filepath.ToSlash(mustRel(workspace, p)))
			}
			return true
		})
	}
	sort.Slice(matches, func(i, j int) bool { return strings.ToLower(matches[i]) < strings.ToLower(matches[j]) })
	paged, off, end := pageStrings(matches, opts...)
	body := "No files found"
	if len(paged) > 0 {
		body = strings.Join(paged, "\n")
	}
	r := withBody(success(fmt.Sprintf("Found %d matching files", len(matches))), body)
	r.Semantics = map[string]any{"offset": off, "returned_count": len(paged), "total_count": len(matches), "has_more": end < len(matches)}
	if end < len(matches) {
		r.Semantics["next_offset"] = end
	}
	return r, nil
}

func mustRel(root, p string) string { r, _ := filepath.Rel(root, p); return r }

func grepIncludeMatches(workspace, searchRoot, candidate, include string) bool {
	include = strings.TrimSpace(include)
	if include == "" || include == "**/*" || include == "**/{*,.*}" || include == "**" {
		return true
	}
	workspaceRelative := filepath.ToSlash(mustRel(workspace, candidate))
	baseRelative := filepath.ToSlash(mustRel(searchRoot, candidate))
	baseName := filepath.Base(candidate)
	workspaceMatch, _ := doublestar.Match(include, workspaceRelative)
	baseMatch, _ := doublestar.Match(include, baseRelative)
	nameMatch, _ := doublestar.Match(include, baseName)
	return workspaceMatch || baseMatch || nameMatch
}

func (SearchService) Grep(root, path, pattern string, opts ...SearchOptions) (ToolResult, error) {
	target, err := resolveReadPath(root, path, true)
	if err != nil {
		return ToolResult{}, err
	}
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return withBody(success("Found 0 matches"), "No files found"), nil
	}
	workspace, _ := resolveWorkspace(root)
	type match struct {
		p string
		n int
		s string
	}
	all := []match{}
	include := ""
	if len(opts) > 0 {
		include = opts[0].Include
	}
	consume := func(p string) {
		if !grepIncludeMatches(workspace, target, p, include) {
			return
		}
		_ = scanLines(p, func(n int, s string) bool {
			if rx.MatchString(s) {
				all = append(all, match{filepath.ToSlash(mustRel(workspace, p)), n, s})
			}
			return len(all) < 5000
		})
	}
	st, _ := os.Stat(target)
	if st != nil && !st.IsDir() {
		consume(target)
	} else {
		_ = walkVisible(workspace, target, func(p string, d os.DirEntry) bool {
			if !d.IsDir() {
				consume(p)
			}
			return len(all) < 5000
		})
	}
	off, limit := 0, 100
	if len(opts) > 0 {
		off = opts[0].Offset
		if opts[0].Limit > 0 {
			limit = opts[0].Limit
			if limit > 500 {
				limit = 500
			}
		}
	}
	if off < 0 {
		off = 0
	}
	if off > len(all) {
		off = len(all)
	}
	end := off + limit
	if end > len(all) {
		end = len(all)
	}
	if len(all) == 0 {
		return withBody(success("Found 0 matches"), "No files found"), nil
	}
	var b strings.Builder
	last := ""
	for _, x := range all[off:end] {
		if x.p != last {
			if b.Len() > 0 {
				b.WriteByte('\n')
			}
			b.WriteString(x.p)
			b.WriteByte('\n')
			last = x.p
		}
		b.WriteString(fmt.Sprintf("Line %d: %s\n", x.n, x.s))
	}
	r := withBody(success(fmt.Sprintf("Found %d matches", len(all))), strings.TrimRight(b.String(), "\n"))
	r.Semantics = map[string]any{"offset": off, "returned_count": end - off, "total_count": len(all), "has_more": end < len(all)}
	if end < len(all) {
		r.Semantics["next_offset"] = end
	}
	return r, nil
